/* MJ original presentation artwork. Each crop belongs to one product.
   Props illustrate the verified flavour profile; they are not additional ingredients.
   Generated to match the existing MJ photographic art direction. */
(() => {
 const atlas="data:image/png;base64,";
 const products=window.MJ_MENU.products.filter(p=>p.edition14);
 const side=1254, tileW=side/3, tileH=side/4, inset=2;
 for(const p of products){
  const i=p.artIndex;
  if(!Number.isInteger(i)||i<0||i>11)throw new Error("Invalid MJ art index");
  const x=(i%3)*tileW+inset, y=Math.floor(i/3)*tileH+inset;
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="828" height="619" viewBox="'+[x,y,tileW-inset*2,tileH-inset*2].join(' ')+'"><image width="1254" height="1254" href="'+atlas+'"/></svg>';
  p.image=URL.createObjectURL(new Blob([svg],{type:"image/svg+xml"}));
 }
})();